INSERT INTO handoffs (session_id, project_id, phase_completed, summary, pending_work, next_action, r2_handoff_path, wbs_code, dod_verdict, claim_sheet) VALUES ('QTQ0lQcDJHFDpEUYGTZHE','qnfo-papers-version-archive-2026-10-25',8,'CMD RED TEAM 2026-10-25: FAIL. The user-facing directive is not live. Live qnfo-gateway is 3.34.0: /api/paper-context/chapter-1 has no version_history; /papers/chapter-1/v/1.1.0 returns HTTP 200 with the current v1.2.0 page and no archive banner; /api/plain/coverage and /api/plain/rebuild are 404. D1 is partially changed: paper_version_history has 160 rows / 88 papers, 2 archive triggers and 1 unique index, but 61 papers still lack at least one prior version (218 expected). plain_summary has 703 rows, 606 contain digits, 298 contain jargon markers, average grade 9.6, max 24.5. The live chapter-1 page still shows Provenance and AI Involvement and Restated for a non-expert reader. The committed candidate 8a599211 is based on 3.32.0; the temp candidate is 3.35.0 based on 3.34.0; main is 3.37.0 with 69 insertions / 21 deletions since 3.34.0, so deploying it would regress 3.35.0-3.37.0. The deploy lock is held by deepchat/QNFO-WIN-22112. Candidate dry-run bundles, but it is not deployable until rebased.','OPEN owner=qnfo-gateway: rebase onto main 3.37.0 and fix plainBatch pagination (select stale rows, not the same newest window), make plainQuality enforcing, reject qr2 revs. OPEN owner=qnfo-paper-indexer: recover the 61 missing prior-version bodies or expose honest tombstones. OPEN owner=qnfo-gateway: regenerate all summaries and verify zero digits / grade <= 10 on a live sample. OPEN owner=qnfo-paper-reviser: add a standards gate for References formatting, detailed Appendices, jargon definitions and glossary. OPEN owner=qnfo-ops: deploy only after the rebase, through POST /ops/deploy, then re-probe version_history, /v/<version>, plain coverage and the live page. OPEN owner=deepchat: provide a raw verbatim archive view or download; the current render strips metadata.','Rebase the candidate onto main 3.37.0; fix plainBatch pagination and quality enforcement; reject qr2; regenerate summaries; then deploy server-side and re-probe. Do not deploy 8a599211 or 3.35.0.',NULL,'PAPERS-VERSION-ARCHIVE-2026-10-25','FAIL','[{"claim": "The live paper-context API exposes the full version history", "evidence": "GET https://papers.qnfo.org/api/paper-context/chapter-1 returned has_version_history=false, versions_len=1, version_history_missing=ABSENT", "confidence": "high", "status": "false"}, {"claim": "A version URL serves that version''s archived full text", "evidence": "GET /papers/chapter-1/v/1.1.0 returned HTTP 200 with the current page: title current, v1.2.0, zero occurrences of v1.1.0 and zero occurrences of Archived version", "confidence": "high", "status": "false"}, {"claim": "The version archive is complete", "evidence": "living-paper paper_version_history has 160 rows / 88 papers; 140 multi-version papers need 218 prior versions; 61 papers still lack at least one prior version with a body", "confidence": "high", "status": "partial"}, {"claim": "The plain-language summaries avoid jargon and detailed numerical analysis", "evidence": "plain_summary has 703 rows; 606 contain a digit (GLOB), 298 contain NDCG/quantum/algorithm; average grade 9.6, max 24.5; live chapter-1 summary contains C(A), NDCG and 0.635", "confidence": "high", "status": "false"}, {"claim": "Extraneous provenance, changelog and version metadata are removed from the rendered paper", "evidence": "live /papers/chapter-1 contains Provenance and AI Involvement twice and Restated for a non-expert reader once; the cleanup function exists only in the uncommitted candidate", "confidence": "high", "status": "false"}, {"claim": "The candidate is safe to deploy", "evidence": "committed artifact 8a599211 is based on a86954da (3.32.0); the temp candidate is 3.35.0 based on 3.34.0; main is 3.37.0 and differs by 69 insertions / 21 deletions across 3.35.0-3.37.0; merge-base ancestor rc=1", "confidence": "high", "status": "false"}, {"claim": "The batch rebuild can regenerate all 703 summaries", "evidence": "plainBatch selects the same first N rows by updated_at on every call and then filters out fresh rows; after one pass it returns 0 candidates and never reaches older rows; plainRevOk still accepts 29 qr2 rows as fresh", "confidence": "high", "status": "false"}, {"claim": "Archived pages are full-text verbatim", "evidence": "the candidate renders cleanPaperMeta(retiredLines(body_md)) on archived pages, removing version/provenance/changelog sections; no raw archived-body API or download is exposed", "confidence": "high", "status": "false"}]');
INSERT INTO wbs_state (project_id,current_phase,total_phases,phase_data,last_updated,session_id,claim_sheet,dod_verdict) VALUES ('qnfo-papers-version-archive-2026-10-25',8,9,'{"P0": "done: live and D1 probes captured", "P1": "partial: 2 triggers + unique index live; 160/218 prior versions archived; 61 papers still missing", "P2": "drafted in temp candidate: archive route, version_history API, Versions tab; not committed or deployed", "P3": "drafted prompt + quality gate; live summaries unchanged and still numeric", "P4": "not implemented: no reviser gate for references, appendices or glossary definitions", "P5": "drafted plainBatch endpoint; corpus-wide pagination and quality enforcement are broken", "P6": "not deployed: candidate base 3.34.0 vs main 3.37.0; deploy lock held by another owner", "P7": "live verification FAIL: no version_history, version URL serves current text, metadata and jargon remain", "P8": "FAIL: red-team verdict recorded; candidate must be rebased and fixed before deploy"}',datetime('now'),'QTQ0lQcDJHFDpEUYGTZHE','[{"claim": "The live paper-context API exposes the full version history", "evidence": "GET https://papers.qnfo.org/api/paper-context/chapter-1 returned has_version_history=false, versions_len=1, version_history_missing=ABSENT", "confidence": "high", "status": "false"}, {"claim": "A version URL serves that version''s archived full text", "evidence": "GET /papers/chapter-1/v/1.1.0 returned HTTP 200 with the current page: title current, v1.2.0, zero occurrences of v1.1.0 and zero occurrences of Archived version", "confidence": "high", "status": "false"}, {"claim": "The version archive is complete", "evidence": "living-paper paper_version_history has 160 rows / 88 papers; 140 multi-version papers need 218 prior versions; 61 papers still lack at least one prior version with a body", "confidence": "high", "status": "partial"}, {"claim": "The plain-language summaries avoid jargon and detailed numerical analysis", "evidence": "plain_summary has 703 rows; 606 contain a digit (GLOB), 298 contain NDCG/quantum/algorithm; average grade 9.6, max 24.5; live chapter-1 summary contains C(A), NDCG and 0.635", "confidence": "high", "status": "false"}, {"claim": "Extraneous provenance, changelog and version metadata are removed from the rendered paper", "evidence": "live /papers/chapter-1 contains Provenance and AI Involvement twice and Restated for a non-expert reader once; the cleanup function exists only in the uncommitted candidate", "confidence": "high", "status": "false"}, {"claim": "The candidate is safe to deploy", "evidence": "committed artifact 8a599211 is based on a86954da (3.32.0); the temp candidate is 3.35.0 based on 3.34.0; main is 3.37.0 and differs by 69 insertions / 21 deletions across 3.35.0-3.37.0; merge-base ancestor rc=1", "confidence": "high", "status": "false"}, {"claim": "The batch rebuild can regenerate all 703 summaries", "evidence": "plainBatch selects the same first N rows by updated_at on every call and then filters out fresh rows; after one pass it returns 0 candidates and never reaches older rows; plainRevOk still accepts 29 qr2 rows as fresh", "confidence": "high", "status": "false"}, {"claim": "Archived pages are full-text verbatim", "evidence": "the candidate renders cleanPaperMeta(retiredLines(body_md)) on archived pages, removing version/provenance/changelog sections; no raw archived-body API or download is exposed", "confidence": "high", "status": "false"}]','FAIL') ON CONFLICT(project_id) DO UPDATE SET current_phase=excluded.current_phase,total_phases=excluded.total_phases,phase_data=excluded.phase_data,last_updated=excluded.last_updated,session_id=excluded.session_id,claim_sheet=excluded.claim_sheet,dod_verdict=excluded.dod_verdict;